// Function to get Rank Colors & Gradients
const getRankStyles = (rank) => {
  switch (rank) {
    case 1:
      return {
        color: "#4CC66E",
        gradient: "linear-gradient(180deg, rgba(76, 198, 110, 0.1) 0%, rgba(76, 198, 110, 0.05) 100%)",
        border: "rgba(76, 198, 110, 0.4)",
        light: "rgba(76, 198, 110, 0.6)",
        glow: "0px 0px 40px rgba(76, 198, 110, 0.25)",
      };
    case 2:
    case 3:
      return {
        color: "#9F6EDA", // Using the purple-ish secondary color seen in DataTable
        gradient: "linear-gradient(180deg, rgba(159, 110, 218, 0.08) 0%, rgba(159, 110, 218, 0.03) 100%)",
        border: "rgba(159, 110, 218, 0.3)",
        light: "rgba(159, 110, 218, 0.5)",
        glow: "0px 0px 30px rgba(159, 110, 218, 0.15)",
      };
    default:
      return {
        color: "#5AC8FA",
        gradient: "linear-gradient(135deg, rgba(90, 200, 250, 0.1) 0%, rgba(90, 200, 250, 0.02) 100%)",
        border: "rgba(90, 200, 250, 0.2)",
        light: "rgba(90, 200, 250, 0.5)",
      };
  }
};

const smoothGrow = keyframes`
  0% {
    clip-path: inset(100% -50% -50% -50%);
    opacity: 0;
    transform: translateY(40px);
  }
  100% {
    clip-path: inset(-50% -50% -50% -50%);
    opacity: 1;
    transform: translateY(0);
  }
`;

