const Leaderboard = () => {
  const theme = useTheme();
  const navigate = useNavigate();
  const { user } = useSelector((state) => state.auth);

  // Data State
  const [topUsersList, setTopUsersList] = useState({ first: null, second: null, third: null });
  const [otherUsersList, setOtherUsersList] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [totalCount, setTotalCount] = useState(0);
  const [isExporting, setIsExporting] = useState(false);

  // Summary + analytics State
  const [summary, setSummary] = useState(null);
  const [coinsSeries, setCoinsSeries] = useState([]);
  const [chartYear, setChartYear] = useState(new Date().getFullYear());
  const [period, setPeriod] = useState("all");

  // Pagination State
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(5);
  const [orderBy, setOrderBy] = useState("totalcoins");
  const [order, setOrder] = useState("desc");

  const token = useSelector((state) => state.auth.token);

  // Navigate to a user's details only when we have a real user id. The
  // leaderboard "rank" is NOT a user id, so never fall back to it (doing so
  // opens the wrong/non-existent user and triggers "Resource not found").
  const goToUserDetails = useCallback((row) => {
    const userId = row?.id;
    if (!userId) {
      toast.error("User profile is unavailable for this entry.");
      return;
    }
    navigate(`/all-users/${userId}`);
  }, [navigate]);

  const fetchLeaderboard = useCallback(async (apiPage, limit) => {
    if (!token) return;
    setIsLoading(true);
    try {
      const queryParams = new URLSearchParams({
        page: apiPage,
        limit: limit,
        sort_by: orderBy,
        sort_order: order,
        q: searchTerm,
      });
      if (period && period !== "all") queryParams.set("period", period);

      const res = await fetch(`${BASE_URL}/rewards/leaderboard?${queryParams.toString()}`, {
        method: "GET",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      const json = await res.json();
      if (!res.ok || json.error) {
        toast.error(json.message || "Failed to fetch leaderboard");
        return;
      }

      setTopUsersList(json.data.topUsers || { first: null, second: null, third: null });
      setOtherUsersList(json.data.otherUsers || []);
      setTotalCount(json.data.pagination?.total || 0);
    } catch (err) {
      console.error("Leaderboard Error:", err);
      toast.error("An error occurred while fetching leaderboard");
    } finally {
      setIsLoading(false);
    }
  }, [token, orderBy, order, searchTerm, period]);

  useEffect(() => {
    if (token) {
      fetchLeaderboard(page + 1, rowsPerPage);
    }
  }, [page, rowsPerPage, fetchLeaderboard, token]);

  // KPI summary (fetched once).
  useEffect(() => {
    if (!token) return;
    apiGetJson("/rewards/leaderboard/summary", token)
      .then((res) => setSummary(res.data || null))
      .catch((err) => console.error("Leaderboard summary error:", err));
  }, [token]);

  // Coins-earned timeseries, scoped to the selected year (grouped by month).
  useEffect(() => {
    if (!token) return;
    apiGetJson("/rewards/leaderboard/timeseries", token, {
      group: "month",
      start_date: `${chartYear}-01-01`,
      end_date: `${chartYear}-12-31`,
    })
      .then((res) => setCoinsSeries(res.data?.series || []))
      .catch((err) => console.error("Coins timeseries error:", err));
  }, [token, chartYear]);

  const handlePeriodChange = useCallback((_e, next) => {
    if (!next) return;
    setPeriod(next);
    setPage(0);
    if (next === "all") {
      setOrderBy("totalcoins");
    } else {
      setOrderBy("periodcoins");
    }
    setOrder("desc");
  }, []);

  const coinsChartData = useMemo(
    () =>
      (coinsSeries || []).map((row) => ({
        month: row.period_start ? dayjs(row.period_start).format("MMM") : "-",
        value: row.coins || 0,
      })),
    [coinsSeries]
  );

  const handleExport = useCallback(async (dates, format) => {
    if (!token) return;
    const toastId = toast.loading(`Exporting leaderboard as ${format.toUpperCase()}...`);
    setIsExporting(true);
    try {
      const queryParams = new URLSearchParams({
        q: searchTerm,
        sort_by: orderBy,
        sort_order: order,
        not_pagination: "true",
        start_date: dates.startDate.format('YYYY-MM-DD'),
        end_date: dates.endDate.format('YYYY-MM-DD'),
      });

      const res = await fetch(`${BASE_URL}/rewards/leaderboard?${queryParams.toString()}`, {
        method: "GET",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      const json = await res.json();
      if (!res.ok || json.error) throw new Error(json.message || "Failed to export");

      // Robust extraction for Leaderboard (combining top and other users)
      let allUsers = [];
      if (json.data) {
          if (json.data.topUsers) {
              allUsers = [...allUsers, ...Object.values(json.data.topUsers).filter(Boolean)];
          }
          if (Array.isArray(json.data.otherUsers)) {
              allUsers = [...allUsers, ...json.data.otherUsers];
          }
      }

      const filename = `Leaderboard_${dates.startDate.format('YYYYMMDD')}_to_${dates.endDate.format('YYYYMMDD')}`;

      await performExport({
        items: allUsers,
        mapper: mapLeaderboardExport,
        format,
        filename,
        sheetName: 'Leaderboard',
        entityName: 'leaderboard entries',
        toastId,
      });
    } catch (err) {
      console.error("Export Error:", err);
      toast.error(err.message || "Export error", { id: toastId });
    } finally {
        setIsExporting(false);
    }
  }, [token, searchTerm, orderBy, order]);

  const first = topUsersList.first;
  const second = topUsersList.second;
  const third = topUsersList.third;

  const handleSearchChange = (term) => {
    setSearchTerm(term);
    setPage(0);
  };

  // Setup generic column renderers
  const columns = useMemo(() => [
    {
      id: "rank",
      label: "Rank",
      sortable: true,
      render: (row) => {
        const isTop3 = row.rank <= 3;
        const styles = getRankStyles(row.rank);
        return (
          <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
            <Box
              sx={{
                width: 32,
                height: 32,
                borderRadius: "50%",
                bgcolor: isTop3 ? alpha(styles.color, 0.15) : "transparent",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontWeight: isTop3 ? 800 : 600,
                color: isTop3 ? styles.color : "#8B8D97",
              }}
            >
              {isTop3 ? <TrophyIcon sx={{ fontSize: 18 }} /> : `#${row.rank}`}
            </Box>
          </Box>
        );
      },
    },
    {
      id: "name",
      label: "User",
      sortable: true,
      render: (row) => (
        <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
          <AvatarView
            src={row.avatar}
            alt={row.name}
            previewTitle={row.name}
            sx={{ width: 40, height: 40 }}
          />
          <Box>
            <Typography
              sx={{ color: "#FFFFFF", fontWeight: 600, fontSize: "0.875rem" }}
            >
              {row.name}
            </Typography>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                {row.currentBadge && (
                    <Box 
                        sx={{ 
                            width: 12, 
                            height: 12, 
                            borderRadius: '50%', 
                            bgcolor: row.currentBadge.color_value || '#FFF',
                            boxShadow: `0 0 6px ${alpha(row.currentBadge.color_value || '#FFF', 0.5)}`
                        }} 
                    />
                )}
                <Typography variant="caption" sx={{ color: row.currentBadge?.color_value || "#8B8D97", fontSize: '0.7rem', fontWeight: 600 }}>
                    {row.currentBadge?.title || row.email}
                </Typography>
            </Box>
          </Box>
        </Box>
      ),
    },
    {
      id: "totalCoins",
      label: "Total Coins",
      sortable: true,
      render: (row) => (
        <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
          <CoinIcon sx={{ fontSize: 16, color: "#FFCC00" }} />
          <Typography sx={{ color: "#FFCC00", fontWeight: 800, fontSize: "0.9rem" }}>
            {row.totalCoins?.toLocaleString()} <span style={{ fontSize: '0.7rem', color: '#8B8D97' }}>coins</span>
          </Typography>
        </Box>
      ),
    },
    ...(period !== "all"
      ? [
          {
            id: "periodcoins",
            label: PERIOD_COLUMN_LABEL[period] || "Earned",
            sortable: true,
            render: (row) => (
              <Typography sx={{ color: "#4CC66E", fontWeight: 700, fontSize: "0.85rem" }}>
                +{(row.periodCoins || 0).toLocaleString()}
              </Typography>
            ),
          },
        ]
      : []),
    {
      id: "earned",
      label: "Earned",
      sortable: true,
      render: (row) => (
        <Typography sx={{ color: "#4CC66E", fontWeight: 600, fontSize: "0.85rem" }}>
          +{(row.earnedCoins || 0).toLocaleString()}
        </Typography>
      ),
    },
    {
      id: "redeemed",
      label: "Redeemed",
      sortable: true,
      render: (row) => (
        <Typography sx={{ color: "#F5A623", fontWeight: 600, fontSize: "0.85rem" }}>
          -{(row.redeemedCoins || 0).toLocaleString()}
        </Typography>
      ),
    },
    {
      id: "lastActive",
      label: "Last Active",
      render: (row) => (
        <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
          <ClockIcon sx={{ fontSize: 14, color: "#8B8D97" }} />
          <Typography sx={{ color: "#8B8D97", fontSize: "0.8rem", whiteSpace: "nowrap" }}>
            {row.lastActive ? dayjs(row.lastActive).format("DD MMM YYYY") : "-"}
          </Typography>
        </Box>
      ),
    },
    {
      id: "badge",
      label: "Current Badge",
      render: (row) => (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
            {row.currentBadge ? (
                <>
                    <Box 
                        sx={{ 
                            width: 24, 
                            height: 24, 
                            borderRadius: '50%',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            bgcolor: alpha(row.currentBadge.color_value || '#FFF', 0.1),
                            color: row.currentBadge.color_value || '#FFF'
                        }}
                    >
                        <ImageWithFallback
                            src={row.currentBadge.badge_image}
                            alt={row.currentBadge.title}
                            fallbackIcon={TrophyIcon}
                            sx={{ width: '100%', height: '100%', p: 0.5, objectFit: 'contain', fontSize: 12 }}
                        />
                    </Box>
                    <Typography sx={{ color: row.currentBadge.color_value || "#FFFFFF", fontSize: "0.85rem", fontWeight: 600 }}>
                        {row.currentBadge.title}
                    </Typography>
                </>
            ) : (
                <Typography sx={{ color: "#555", fontSize: "0.85rem" }}>No Badge</Typography>
            )}
        </Box>
      ),
    },
  ], [period]);

  // Removed useMemo filter logic - API handles it now
  const displayData = otherUsersList;

  const handleSortChange = (property) => {
    const isAsc = orderBy === property && order === "asc";
    setOrder(isAsc ? "desc" : "asc");
    setOrderBy(property);
    setPage(0);
  };

  const kpis = useMemo(
    () => [
      { title: "Total Players", value: summary?.total_players || 0, icon: <PlayersIcon />, color: "#4CC66E" },
      { title: "Coins in Circulation", value: summary?.coins_in_circulation || 0, icon: <CirculationIcon />, color: "#FFCC00" },
      { title: "Earned (7 days)", value: summary?.coins_earned_week || 0, icon: <TrendingIcon />, color: "#9F6EDA" },
      { title: "Earned (30 days)", value: summary?.coins_earned_month || 0, icon: <MonthIcon />, color: "#5AC8FA" },
      { title: "Avg Coins / User", value: summary?.avg_coins || 0, icon: <AvgIcon />, color: "#F5A623" },
    ],
    [summary]
  );

  const periodToggle = (
    <ToggleButtonGroup
      value={period}
      exclusive
      onChange={handlePeriodChange}
      size="small"
      sx={{
        flexWrap: "wrap",
        bgcolor: "rgba(255,255,255,0.04)",
        borderRadius: "10px",
        p: "3px",
        "& .MuiToggleButton-root": {
          border: "none",
          borderRadius: "8px !important",
          color: "rgba(255,255,255,0.6)",
          fontFamily: "'Montserrat', sans-serif",
          fontWeight: 600,
          fontSize: "0.72rem",
          textTransform: "none",
          px: { xs: 1.2, sm: 1.6 },
          py: 0.6,
          "&.Mui-selected": {
            bgcolor: "#4CC66E",
            color: "#04140a",
            "&:hover": { bgcolor: "#3EB05D" },
          },
          "&:hover": { bgcolor: "rgba(76,198,110,0.12)" },
        },
      }}
    >
      {PERIOD_OPTIONS.map((opt) => (
        <ToggleButton key={opt.value} value={opt.value}>
          {opt.label}
        </ToggleButton>
      ))}
    </ToggleButtonGroup>
  );

  return (
    <Box sx={{ p: { xs: 2, md: 4 }, bgcolor: "#050805", minHeight: "100vh" }}>

      {/* Top 3 Cards Section */}
      <Box sx={{ mb: 8 }}>
        <Box sx={{ mb: 4 }}>
          <Typography
            variant="h3"
            sx={{
              color: "#FFF",
              fontWeight: 900,
              fontFamily: "'Montserrat', sans-serif",
              letterSpacing: "-1px",
            }}
          >
            Top Ranking
          </Typography>
        </Box>

        <Grid
          container
          spacing={4}
          alignItems="flex-start"
          justifyContent="center"
        >
          {/* Second Place (Left) */}
          <Grid
            item
            xs={12}
            sm={4}
            md={4}
            lg={4}
            sx={{
              order: { xs: 2, sm: 1 },
              display: "flex",
              justifyContent: "center",
            }}
          >
            {second && (
              <LeaderboardCard 
                user={second} 
                onClick={() => goToUserDetails(second)} 
                animationDelay="300ms"
              />
            )}
          </Grid>

          {/* First Place (Center) */}
          <Grid
            item
            xs={12}
            sm={4}
            md={4}
            lg={4}
            sx={{
              order: { xs: 1, sm: 2 },
              display: "flex",
              justifyContent: "center",
            }}
          >
            {first && (
              <LeaderboardCard 
                user={first} 
                onClick={() => goToUserDetails(first)} 
                animationDelay="0ms"
              />
            )}
          </Grid>

          {/* Third Place (Right) */}
          <Grid
            item
            xs={12}
            sm={4}
            md={4}
            lg={4}
            sx={{
              order: { xs: 3, sm: 3 },
              display: "flex",
              justifyContent: "center",
            }}
          >
            {third && (
              <LeaderboardCard 
                user={third} 
                onClick={() => goToUserDetails(third)} 
                animationDelay="600ms"
              />
            )}
          </Grid>
        </Grid>
      </Box>

      {/* KPI Summary Strip */}
      <Box
        sx={{
          display: "grid",
          gridTemplateColumns: {
            xs: "1fr",
            sm: "repeat(2, 1fr)",
            md: "repeat(3, 1fr)",
            lg: "repeat(5, 1fr)",
          },
          gap: { xs: 1.5, md: 2.5 },
          mb: 4,
        }}
      >
        {kpis.map((kpi) => (
          <StatCard
            key={kpi.title}
            title={kpi.title}
            value={kpi.value}
            icon={kpi.icon}
            iconColor={kpi.color}
          />
        ))}
      </Box>

      {/* Badge Distribution */}
      {summary?.badge_distribution?.length > 0 && (
        <Box
          sx={{
            display: "flex",
            flexWrap: "wrap",
            gap: 1,
            mb: 4,
            alignItems: "center",
          }}
        >
          <Typography
            sx={{
              color: "rgba(255,255,255,0.5)",
              fontSize: "0.75rem",
              fontWeight: 700,
              textTransform: "uppercase",
              letterSpacing: "0.08em",
              mr: 0.5,
              fontFamily: "'Montserrat', sans-serif",
            }}
          >
            Badge Tiers:
          </Typography>
          {summary.badge_distribution.map((b) => (
            <Chip
              key={b.title}
              size="small"
              label={`${b.title} · ${b.count}`}
              sx={{
                bgcolor: alpha(b.color_value || "#8B8D97", 0.15),
                color: b.color_value || "#8B8D97",
                fontWeight: 700,
                fontSize: "0.72rem",
                fontFamily: "'Montserrat', sans-serif",
                border: `1px solid ${alpha(b.color_value || "#8B8D97", 0.3)}`,
              }}
            />
          ))}
        </Box>
      )}

      {/* Coins Earned Over Time */}
      <Box sx={{ mb: 6 }}>
        <AreaGraph
          title="Coins Earned Over Time"
          data={coinsChartData}
          lineColor="#FFCC00"
          gradientFrom="rgba(255,204,0,0.30)"
          gradientTo="rgba(255,204,0,0.00)"
          suffix=" coins"
          selectedYear={chartYear}
          onYearChange={(yr) => setChartYear(yr)}
        />
      </Box>

      {/* Leaderboard Data Table */}
      <DataTable
        title="Global Leaderboard"
        columns={columns}
        data={displayData}
        isLoading={isLoading}
        searchTerm={searchTerm}
        onSearchChange={handleSearchChange}
        filters={periodToggle}
        onExport={handleExport}
        isExporting={isExporting}
        onViewClick={(row) => goToUserDetails(row)}
        orderBy={orderBy}
        order={order}
        onSortChange={handleSortChange}
        pagination={{
          page: page,
          rowsPerPage: rowsPerPage,
          totalCount: totalCount,
          onPageChange: (_, newPage) => setPage(newPage),
          onRowsPerPageChange: (e) => {
            setRowsPerPage(parseInt(e.target.value, 10));
            setPage(0);
          },
        }}
        emptyTitle="No players found"
        emptyMessage="Try adjusting your search criteria."
      />
    </Box>
  );
};

export default Leaderboard;
